import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{"title":"Roadmap"},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1782667185000}'),l={name:"roadmap.md"};function o(n,e,s,d,m,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>Planned future directions for Synapse.</p><h2 id="current-0-1-x" tabindex="-1">Current (0.1.x) <a class="header-anchor" href="#current-0-1-x" aria-label="Permalink to &quot;Current (0.1.x)&quot;">​</a></h2><ul><li>✅ Core Agent trait</li><li>✅ ReAct agent (ChatModelAgent, GraphReActAgent)</li><li>✅ Tool framework (BaseTool, InvokableTool, EnhancedInvokableTool)</li><li>✅ MultiAgent (Router, Orchestrator, Handoff, Hybrid)</li><li>✅ RAG (chunking, embedding, vector store, retriever)</li><li>✅ MCP client (stdio + HTTP)</li><li>✅ A2A protocol</li><li>✅ Cross-platform (native + WASM)</li><li>✅ OpenAI + Anthropic LLM support</li><li>✅ Document unification + JSON serialization</li><li>✅ Apache 2.0 licensed</li><li>✅ 205 tests</li></ul><h2 id="short-term-0-2-x" tabindex="-1">Short Term (0.2.x) <a class="header-anchor" href="#short-term-0-2-x" aria-label="Permalink to &quot;Short Term (0.2.x)&quot;">​</a></h2><ul><li>[ ] More vector store backends (LanceDB, Qdrant, pgvector)</li><li>[ ] Streaming response support for all chat models</li><li>[ ] Full resume/checkpoint for long-running agents</li><li>[ ] Built-in A2A server (axum-based)</li><li>[ ] More document parsers (PDF, DOCX, etc.)</li><li>[ ] HTML-aware chunker</li><li>[ ] Code-aware chunker (function/class boundaries)</li></ul><h2 id="medium-term-0-3-x" tabindex="-1">Medium Term (0.3.x+) <a class="header-anchor" href="#medium-term-0-3-x" aria-label="Permalink to &quot;Medium Term (0.3.x+)&quot;">​</a></h2><ul><li>[ ] Agent observability (OpenTelemetry integration)</li><li>[ ] Prompt template DSL</li><li>[ ] Agent memory management (short-term + long-term)</li><li>[ ] Multi-modal support (vision, audio)</li><li>[ ] Distributed agent execution</li><li>[ ] PFC runtime integration (deploy to PFC)</li><li>[ ] Neuron LLM runtime integration</li></ul><h2 id="long-term" tabindex="-1">Long Term <a class="header-anchor" href="#long-term" aria-label="Permalink to &quot;Long Term&quot;">​</a></h2><ul><li>[ ] Visual agent builder (no-code)</li><li>[ ] Agent marketplace / registry</li><li>[ ] Performance benchmarks</li><li>[ ] Production deployment guides</li></ul><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>Want to help shape the roadmap? Open an issue on GitHub or check out <a href="https://github.com/synapse-rs/synapse/blob/master/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>.</p>',12)])])}const p=a(l,[["render",o]]);export{h as __pageData,p as default};
